// Loop over input items and add a new field called 'myNewField' to the JSON of each one

function toAction(httpResponse, filepathPrefix){

  let actions = []

  let records = []
  records = records.concat(httpResponse?.done || [])
  records = records.concat(httpResponse?.queue || [])
    records = records.concat(httpResponse?.pending || [])


  for(let a of records){

    let actionStatus = "ActiveActionStatus"
    actionStatus = a.status=="finished" ? "CompletedActionStatus" : actionStatus
    actionStatus = a.status=="error" ? "FailedActionStatus" : actionStatus


    let action = {
      "@type": "Action",
      "@id": "https://metube.tactik8.com/scrape/" + (a?.id || ""),
      "actionStatus": actionStatus,
      "object": {
        "@type": "WebPage",
        "@id": a.url + "#webpage",
        "url": a.url
      },
      "result": {
        "@type": "VideoObject",
        "@id": a.url + "#videoobject",
        "headline": a.title,
        "contentUrl": [filepathPrefix, a.folder, a.filename].filter(x => x).join('/'),
        "url": a.url
      }
    }
    actions.push(action)
  }

  return actions

}




for (const item of $input.all()) {

  item.json.result = toAction(item.json.config.apiResult, item.json.config.filepathPrefix)
}

return $input.all();

// Loop over input items and add a new field called 'myNewField' to the JSON of each one

for (const item of $input.all()) {

  let r = item.json.apiResponses.find(x => x?.['object']?.url == item.json.action.object.url)
  delete item.json.apiResponses
  item.json.action.result = r
}

return $input.all();

